import { useState, useEffect } from 'react'
import { Dialog, DialogBackdrop, DialogPanel, DialogTitle } from '@headlessui/react'
import { ExclamationTriangleIcon, XMarkIcon } from '@heroicons/react/24/outline'
import { useSelector, useDispatch } from 'react-redux'
import { setGamePlayed } from '../store/reducers/gameSlice'

export default function GameModal() {
    const [open, setOpen] = useState(false)
    const { gamePlayed } = useSelector((state) => state.games);
    const { gameUrl } = useSelector((state) => state.games || {});
    const dispatch = useDispatch();

    useEffect(() => {
        if (gamePlayed) {
            setOpen(true);
        }
    }, [gamePlayed]);

    const handleClose = () => {
        setOpen(false);
        dispatch(setGamePlayed(false));
    };

    return (
        <Dialog open={open} onClose={handleClose} className="relative z-1000">
            <DialogBackdrop
                transition
                className="fixed inset-0 bg-gray-500/75 transition-opacity data-closed:opacity-0 data-enter:duration-300 data-enter:ease-out data-leave:duration-200 data-leave:ease-in"
            />

            <div className="fixed inset-0 z-10 w-screen android:h-screen md:h-screen">
                <div className="flex h-full w-full">
                    <DialogPanel
                        transition
                        className="relative transform overflow-hidden bg-white text-left shadow-xl transition-all data-closed:translate-y-4 data-closed:opacity-0 data-enter:duration-300 data-enter:ease-out data-leave:duration-200 data-leave:ease-in w-full h-full"
                    >
                        <div className="bg-white h-full w-full">
                            <div className="flex flex-col relative h-full">
                                <div className="flex absolute top-5 right-5 justify-end p-4">
                                    <button
                                        onClick={handleClose}
                                        className="rounded-full bg-red-100 p-2"
                                    >
                                        <XMarkIcon aria-hidden="true" className="size-6 text-red-600" />
                                    </button>
                                </div>
                                <div className="flex-1">
                                    {window.navigator.userAgent.includes('Android') ? (
                                        <iframe
                                            src={gameUrl}
                                            className="w-full border-none h-screen overflow-hidden"
                                            title="Game Frame"
                                            allow='fullscreen'
                                        />
                                    ) : window.navigator.userAgent.includes('iPhone') || window.navigator.userAgent.includes('iPad') ? (
                                        <iframe
                                            src={gameUrl}
                                            className="w-full border-none h-[-webkit-fill-available] overflow-hidden"
                                            title="Game Frame"
                                            allow='fullscreen'
                                        />
                                    ) : (
                                        <iframe
                                            src={gameUrl}
                                            className="w-full border-none h-full overflow-hidden"
                                            title="Game Frame"
                                            allow='fullscreen'
                                        />
                                    )}
                                </div>
                            </div>
                        </div>
                    </DialogPanel>
                </div>
            </div>
        </Dialog>
    )
}