import React, { createContext, useState } from "react";
import axios from "axios";
const APIContext = createContext(null);

export const ApiProvider = ({ children }) => {
    const [data, setData] = useState(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);

    const getGameList = async (provider) => {
        const res = await axios.post(`${process.env.REACT_APP_API_URL}api/v2/casinos/get-gamelists`, {
            provider,
        });
        return res;
    }

    const triggerGame = async (BankGroupId, GameId) => {
        const res = await axios.post(`${process.env.REACT_APP_API_URL}api/v2/casinos/create-demo`, {
            BankGroupId,
            GameId,
        });
        return res;
    }

    const login = async (email, password) => {
        const data = await axios.post(`${process.env.REACT_APP_API_URL}api/v2/users/signin`, {
            email,
            password,
        });
        return data;
    };

    return (
        <APIContext.Provider
            value={{
                getGameList,
                triggerGame,
                login
            }}
        >
            {children}
        </APIContext.Provider>
    );
};

export default APIContext;